import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.DnrXFDHb.js";const d=JSON.parse('{"title":"第 17 章 Agent Loss Scale","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/17-loss-scale-agent.md","filePath":"chapters/17-loss-scale-agent.md"}'),o={name:"chapters/17-loss-scale-agent.md"};function l(r,e,i,c,h,g){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="第-17-章-agent-loss-scale" tabindex="-1">第 17 章 Agent Loss Scale <a class="header-anchor" href="#第-17-章-agent-loss-scale" aria-label="Permalink to &quot;第 17 章 Agent Loss Scale&quot;">​</a></h1><h2 id="_17-1-agent-训练的特殊性" tabindex="-1">17.1 Agent 训练的特殊性 <a class="header-anchor" href="#_17-1-agent-训练的特殊性" aria-label="Permalink to &quot;17.1 Agent 训练的特殊性&quot;">​</a></h2><p>Agent 模型的输出包含多个部分，重要性不同：</p><ul><li><strong>Thought/Final Answer</strong>：模型自主生成，应重点训练（weight=1.0）</li><li><strong>Action/Action Input</strong>：工具调用格式，需要精确学习（weight=2.0）</li><li><strong>Observation</strong>：外部环境返回，不应训练（weight=0.0）</li></ul><p>示例输出：</p><pre><code>Thought: 我需要查询天气
Action: get_weather
Action Input: {city: Beijing}
Observation: 北京今天晴，25C
Thought: 我知道答案了
Final Answer: 北京今天是晴天，25C
</code></pre><h2 id="_17-2-reactlossscale" tabindex="-1">17.2 REACTLossScale <a class="header-anchor" href="#_17-2-reactlossscale" aria-label="Permalink to &quot;17.2 REACTLossScale&quot;">​</a></h2><p>配置文件 react.json：</p><pre><code>{
    Action: [2.0, 2.0],
    Action Input: [2.0, 2.0],
    Thought: [1.0, 1.0],
    Final Answer: [1.0, 1.0],
    Observation: [2.0, 0.0]
}
</code></pre><p>格式说明：[delimiter_weight, content_weight]</p><ul><li>第一个值：分隔符本身的权重</li><li>第二个值：内容的权重</li></ul><p>因此 Observation: [2.0, 0.0] 表示 Observation 后面内容的权重 = 0.0（不参与训练）。</p><h2 id="_17-3-hermeslossscale" tabindex="-1">17.3 HermesLossScale <a class="header-anchor" href="#_17-3-hermeslossscale" aria-label="Permalink to &quot;17.3 HermesLossScale&quot;">​</a></h2><p>适用于 Hermes 格式的 Agent，配置 hermes.json。</p><h2 id="_17-4-qwenlossscale" tabindex="-1">17.4 QwenLossScale <a class="header-anchor" href="#_17-4-qwenlossscale" aria-label="Permalink to &quot;17.4 QwenLossScale&quot;">​</a></h2><p>适用于 Qwen Agent 格式，配置 qwen.json。</p><h2 id="_17-5-agentflanlossscale" tabindex="-1">17.5 AgentFlanLossScale <a class="header-anchor" href="#_17-5-agentflanlossscale" aria-label="Permalink to &quot;17.5 AgentFlanLossScale&quot;">​</a></h2><p>AgentFlan 支持 query 和 response 分别设置权重映射。</p><h2 id="_17-6-ignoreemptythinklossscale" tabindex="-1">17.6 IgnoreEmptyThinkLossScale <a class="header-anchor" href="#_17-6-ignoreemptythinklossscale" aria-label="Permalink to &quot;17.6 IgnoreEmptyThinkLossScale&quot;">​</a></h2><p>用于忽略空的思维链（empty thinking）标签。</p><h2 id="_17-7-组合使用" tabindex="-1">17.7 组合使用 <a class="header-anchor" href="#_17-7-组合使用" aria-label="Permalink to &quot;17.7 组合使用&quot;">​</a></h2><p>Loss Scale 支持串联组合：</p><pre><code>swift sft --loss_scale react+ignore_empty_think ...
</code></pre><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>要点 1</strong>：Agent Loss Scale 通过配置实现细粒度的损失控制</li><li><strong>要点 2</strong>：不同 Agent 格式有对应的 Loss Scale 实现</li><li><strong>要点 3</strong>：支持串联组合，灵活性极强</li></ul>`,25)])])}const _=a(o,[["render",l]]);export{d as __pageData,_ as default};
